mapper.select:
SELECT d.id AS id_device, d.devicename AS device_name, d.serialnumber AS serial, d.devicename AS tenant_name, IFNULL(tm.multiplier, 1) AS multiplier, loc.location, d.datatablename, d.`status` AS device_status FROM tenant_meter tm INNER JOIN device d ON d.id = tm.id_device LEFT JOIN ( SELECT m.id_device, MIN(r.`name`) AS location FROM site_area_building_floor_room_device_map m INNER JOIN site_area_building_floor_room r ON r.id = m.id_room WHERE r.id_site = #{id_site} GROUP BY m.id_device ) loc ON loc.id_device = d.id WHERE tm.id_site = #{id_site} AND tm.`status` = 1 AND d.id_site = #{id_site} AND d.is_delete = 0
AND d.id = #{id_device}
ORDER BY d.serialnumber
